function questionHTML(i,j,q){let key=`${i}:${j}`,done=!!state.done[key];return `<div class="question ${done?'is-correct':''}" id="box-${i}-${j}"><div class="qhead"><div>${q.quiz?`<span class="quiz-label">QUIZ QUESTION</span><span>${escapeHTML(q.quiz)} · ${escapeHTML(q.ref||'')}</span>`:q.homework?`<span class="quiz-label homework-label">${escapeHTML(q.homework.toUpperCase())}</span><span>${escapeHTML(q.ref||'')}</span>`:`<span>Practice ${j+1}</span>`}</div><span class="status-pill" id="status-${i}-${j}">${done?'✓ Mastered':'Not attempted'}</span></div><div class="qtext">${mathHTML(q.q)}</div><div class="answerrow"><input type="text" id="input-${i}-${j}" aria-label="Answer for practice question ${j+1}" placeholder="Type your answer…" value="${escapeHTML(state.answers[key]||'')}" onkeydown="if(event.key==='Enter')check(${i},${j})" oninput="saveDraft(${i},${j},this.value)"><button class="btn primary" onclick="check(${i},${j})">Check answer</button><button class="btn ghost" onclick="toggleSolution(${i},${j})">View solution</button></div><div id="feedback-${i}-${j}"></div><div id="solution-${i}-${j}" class="solution hide"><strong>Answer: ${mathHTML(q.a)}</strong><div>${mathHTML(q.why)}</div><div style="margin-top:14px"><button class="btn" onclick="mark(${i},${j})">${done?'✓ Mastered':'Mark as mastered'}</button></div></div></div>`}
function saveDraft(i,j,v){state.answers[`${i}:${j}`]=v;save()};function parseNumber(s){s=s.trim().replace(/,/g,'');let m=s.match(/^([+-]?\d+(?:\.\d+)?)\s*\/\s*([+-]?\d+(?:\.\d+)?)$/);return m?Number(m[1])/Number(m[2]):Number(s)};function normalize(s){return String(s).toLowerCase().trim().replace(/[\s()]/g,'').replace(/−/g,'-').replace(/\byes\b/g,'yes').replace(/\bno\b/g,'no')};function equivalent(guess,ans){let a=parseNumber(guess),b=parseNumber(ans);if(guess.trim()&&ans.trim()&&Number.isFinite(a)&&Number.isFinite(b))return Math.abs(a-b)<1e-5;return normalize(guess)===normalize(ans)||normalize(guess).replace(/^[a-z]+=/,'')===normalize(ans)};function check(i,j){let key=`${i}:${j}`,q=DATA[i].qs[j],input=el(`input-${i}-${j}`),v=input.value;state.answers[key]=v;let yes=equivalent(v,q.a)||(q.accept||[]).some(a=>equivalent(v,a));if(yes)state.done[key]=true;save();let box=el(`box-${i}-${j}`);box.classList.toggle('is-correct',!!state.done[key]);box.classList.toggle('is-incorrect',!yes&&!state.done[key]);el(`feedback-${i}-${j}`).innerHTML=`<div class="feedback ${yes?'good':'bad'}">${yes?'✓ That’s right — nice work.':'Not quite. Review the worked solution and give it another try.'}</div>`;if(!yes)el(`solution-${i}-${j}`).classList.remove('hide');el(`status-${i}-${j}`).textContent=state.done[key]?'✓ Mastered':'Try again';renderSidebar()};function toggleSolution(i,j){el(`solution-${i}-${j}`).classList.toggle('hide')};function toggleAllSolutions(){hideSolutions=!hideSolutions;document.querySelectorAll('.solution').forEach(x=>x.classList.toggle('hide',hideSolutions))};function mark(i,j){state.done[`${i}:${j}`]=true;save();openTopic(i)};
