function renderStepSolution(i,j,q){
 const steps=(q.solutionSteps&&q.solutionSteps.length?q.solutionSteps:[q.why]);
 return `<div class="solution-heading">Step-by-step solution</div><ol class="walkthrough">${steps.map(s=>`<li>${mathHTML(s)}</li>`).join('')}</ol><div class="answer-final"><span>Final answer</span><strong>${mathHTML(q.a)}</strong></div>`;
}
const oldQuestionHTML=questionHTML;
questionHTML=function(i,j,q){let html=oldQuestionHTML(i,j,q);
  html=html.replace(`<strong>Answer: ${mathHTML(q.a)}</strong><div>${mathHTML(q.why)}</div>`,renderStepSolution(i,j,q));
  html=html.replace(`onclick="toggleSolution(${i},${j})">View solution`, `onclick="toggleSolution(${i},${j})">Step-by-step solution`);
  html=html.replace(`onclick="toggleSolution(${i},${j})">Step-by-step solution</button>`,`onclick="toggleSolution(${i},${j})">Step-by-step solution</button><button class="btn ghost ask-question" onclick="askAboutProblem(${i},${j})">Ask AI about this</button>`);
  return html;
};
