// Homework navigator: deliberately separate instructor assignments from original practice.
let homeworkOnly=false;
const _renderTopicWithNewNotes=renderTopic;
renderTopic=function(scroll=true){
  _renderTopicWithNewNotes(scroll);
  if(topicTab==='practice' && DATA[active]?.qs.some(q=>q.homework)){
    const questions=document.getElementById('questions');
    if(questions){
      const filter=document.createElement('label');filter.className='quizFilter';
      filter.innerHTML='<input type="checkbox" id="homeworkOnly" '+(homeworkOnly?'checked':'')+'> Homework / textbook / review questions only';
      questions.before(filter);
      filter.querySelector('input').addEventListener('change',e=>{homeworkOnly=e.target.checked;refreshQuestions();typesetVisibleMath()});
      if(homeworkOnly)refreshQuestions();
    }
  }
};
const _refreshQuestionsHw=refreshQuestions;
refreshQuestions=function(){
  _refreshQuestionsHw();
  if(homeworkOnly){
    const root=document.getElementById('questions');if(root){
      DATA[active].qs.forEach((q,j)=>{if(!q.homework){const el=document.getElementById(`box-${active}-${j}`);if(el)el.remove()}});
      if(!root.querySelector('.question'))root.innerHTML='<p class="muted">No homework questions match this filter.</p>';
    }
  }
};
const _openTopicHw=openTopic;
openTopic=function(i,tab='learn'){homeworkOnly=false;_openTopicHw(i,tab)};
